# -*- coding: utf-8 -*-
from ._helpers import intro, schema, fall, mc

KURS = dict(
    id="u09", gebiet="upc", titel="Berufung und Rechtsbehelfe",
    untertitel="Statthaftigkeit, Frist, Beschwer, aufschiebende Wirkung, neues Vorbringen, Entscheidung und Wiederaufnahme",
    farbe="#6d28d9", icon="pruefungspunkt",
    beschreibung="Der Weg nach Luxemburg: Welche Entscheidungen und Anordnungen des Gerichts erster Instanz frei anfechtbar sind und welche die Zulassung oder die Ermessensüberprüfung brauchen (EOFlow/Insulet), wann die Berufungsfrist beginnt (Belkin/Philips), wer beschwert ist und wie Anschlussberufung und bedingte Berufung funktionieren (Abbott/Sinocare, Emboline/AorticLab), was der Streithelfer darf (Strabag/Swarco), wann die Berufung aufschiebende Wirkung hat (Amycel, Siemens/Hologic), was in der Berufung neu vorgebracht werden darf (Hefei/Grundfos), wie das Berufungsgericht entscheidet und zurückwirkt (Kodak/Fujifilm) und wann ein rechtskräftiges Verfahren wiederaufgenommen wird (Suinno/Microsoft).",
    kapitel=[
        dict(id="u09a", titel="Statthaftigkeit und Frist (Art. 73 EPGÜ, R. 220 bis 224 VerfO)", einheiten=[
            schema("u09a-0", "Prüfungsschema: Berufung zum Berufungsgericht", "upc_schema_berufung",
                   "Sechs Stationen: Statthaftigkeit (welche Entscheidung oder Anordnung, mit oder ohne Zulassung), Frist und Form, Beschwer mit Anschlussberufung und Streithelfer, aufschiebende Wirkung, Prüfungsumfang mit neuem Vorbringen, Entscheidung des Berufungsgerichts."),
            intro("u09a-1", "Drei Wege zum Berufungsgericht",
                  "Art. 73 EPGÜ unterscheidet **Entscheidungen** und **Anordnungen**. Gegen Endentscheidungen des Gerichts erster Instanz und Entscheidungen, die das Verfahren bezüglich einer Partei beenden, ist die Berufung ohne weiteres statthaft, Frist zwei Monate ab Zustellung (Art. 73 Abs. 1 EPGÜ, R. 220.1 lit. a, b, R. 224.1 lit. a VerfO); die Berufungsbegründung folgt binnen vier Monaten (R. 224.2 lit. a). Ebenso frei anfechtbar sind die in Art. 73 Abs. 2 lit. a EPGÜ genannten Anordnungen nach Art. 49 Abs. 5, 59 bis 62 und 67 EPGÜ, also Sprachwechsel, Beweisvorlage, Beweissicherung, Arrest, einstweilige Maßnahmen und Auskunft, hier aber binnen **15 Tagen** (R. 220.1 lit. c, R. 224.1 lit. b). Alle **anderen Anordnungen** – verfahrensleitende Anordnungen, Streitwertfestsetzung, Zwangsgeldfestsetzung, Vertraulichkeitsanordnungen, Entscheidungen nach R. 333 – sind nur zusammen mit der Berufung gegen die Endentscheidung angreifbar oder wenn das Gericht erster Instanz die Berufung **zulässt** (Art. 73 Abs. 2 lit. b EPGÜ, R. 220.2 VerfO). Verweigert es die Zulassung binnen 15 Tagen, kann binnen weiterer 15 Kalendertage beim Berufungsgericht der Antrag auf **Ermessensüberprüfung** (discretionary review) gestellt werden, über den der ständige Richter entscheidet und den er ohne Begründung abweisen kann (R. 220.3, 220.4 VerfO). Die Berufung kann auf rechtliche und tatsächliche Gesichtspunkte gestützt werden (Art. 73 Abs. 3), neue Tatsachen und Beweismittel aber nur unter den Voraussetzungen des Art. 73 Abs. 4 EPGÜ und der R. 222.2 VerfO. Für jedes Berufungsverfahren ist die Gebühr zu zahlen (R. 228, R. 370.5 VerfO).",
                  concepts=["upc_berufung", "upc_ermessensueberpruefung", "upc_berufungsfrist"], norms=["Art. 73 Abs. 1 EPGÜ", "Art. 73 Abs. 2 EPGÜ", "R. 220 VerfO", "R. 224 VerfO"],
                  distinctions=["d_upc_berufung_entscheidung_anordnung"]),
            mc("u09a-2", "Frei anfechtbar oder nur mit Zulassung?",
                "Gegen welche Anordnung des Gerichts erster Instanz kann die beschwerte Partei Berufung einlegen, ohne dass es einer Zulassung durch das Gericht erster Instanz oder einer Ermessensüberprüfung bedarf?",
                ["Die Festsetzung eines Zwangsgelds nach R. 354.4 VerfO wegen Verstoßes gegen eine Unterlassungsanordnung.",
                 "Die Anordnung einstweiliger Maßnahmen nach Art. 62 EPGÜ.",
                 "Die Festsetzung des Streitwerts nach R. 370.6 VerfO im Tenor der Endentscheidung.",
                 "Die Verweigerung einer Fristverlängerung nach R. 9.3 VerfO durch den Berichterstatter."],
                1,
                ["**Richtig ist die zweite Option.** Anordnungen nach Art. 49 Abs. 5, 59, 60, 61, 62 und 67 EPGÜ sind nach Art. 73 Abs. 2 lit. a EPGÜ, R. 220.1 lit. c VerfO ohne Zulassung anfechtbar, binnen 15 Tagen nach Zustellung (R. 224.1 lit. b VerfO); die Anordnung einstweiliger Maßnahmen nach Art. 62 EPGÜ gehört dazu, ebenso ihre Ablehnung. Die Berufung hindert die Fortsetzung des Ausgangsverfahrens nicht (Art. 74 Abs. 3 EPGÜ).",
                 "Die anderen drei Anordnungen fallen unter R. 220.2 VerfO: Die **Zwangsgeldfestsetzung** ist keine Anordnung nach Art. 73 Abs. 2 lit. a EPGÜ, auch wenn sie eine einstweilige Maßnahme vollstreckt (EPG-BerG EOFlow/Insulet; R. 354.4 Satz 5 VerfO verweist ausdrücklich auf R. 220.2). Die **Streitwertfestsetzung** ist eine Verfahrensentscheidung, gegen die R. 220.2, 220.3 gelten, auch wenn sie im Tenor steht (EPG-BerG Kodak/Fujifilm 2026). Die **Fristverlängerung** ist eine verfahrensleitende Anordnung des Berichterstatters; gegen sie ist zunächst die Überprüfung durch den Spruchkörper nach R. 333 VerfO zu beantragen, erst dessen Entscheidung kann mit Zulassung oder nach Ermessensüberprüfung angefochten werden (R. 220.3 Satz 2 VerfO)."],
                merke="Frei anfechtbar: Endentscheidung und die Anordnungen nach Art. 49 Abs. 5, 59 bis 62, 67. Alles andere: Zulassung oder Ermessensüberprüfung.",
                level=2, concepts=["upc_berufung", "upc_ermessensueberpruefung"], norms=["Art. 73 Abs. 2 EPGÜ", "R. 220.1 VerfO", "R. 220.2 VerfO", "R. 333 VerfO"],
                cases=["upc_coa_eoflow_insulet_zwangsgeld_berufung", "upc_coa_kodak_fujifilm_aufhebung_zwangsgeld"], step="step:upc_schema_berufung.1.2"),
            fall("u09a-3", "Berufung gegen das Zwangsgeld",
                 "Auf Antrag von Insulet setzt die Lokalkammer gegen EOFlow ein Zwangsgeld von 300.000 EUR fest, weil EOFlow einer einstweiligen Maßnahme nach Art. 62 EPGÜ zuwidergehandelt habe. Die Lokalkammer lässt die Berufung nicht zu. EOFlow legt binnen 15 Tagen Berufung beim Berufungsgericht ein und meint, die Festsetzung sei als Vollzug der einstweiligen Maßnahme eine Anordnung „nach Art. 62 EPGÜ“ im Sinne des Art. 73 Abs. 2 lit. a EPGÜ. Hilfsweise beantragt sie die Ermessensüberprüfung.",
                 "Ist die Berufung als solche ohne Zulassung zulässig?", False,
                 ["**Nein!** Anordnungen zur Festsetzung eines Zwangsgelds nach Art. 82 Abs. 4 EPGÜ, R. 354.4 VerfO sind **keine Anordnungen nach Art. 73 Abs. 2 lit. a EPGÜ oder R. 220.1 lit. c VerfO**, auch wenn sie der Durchsetzung einer einstweiligen Maßnahme dienen. Sie beruhen auf einer eigenen Rechtsgrundlage im Vollstreckungsrecht und ergehen in einem eigenen Verfahren (R. 354.4, R. 264 VerfO). Die Berufung ist nur zulässig, wenn das Gericht erster Instanz sie zulässt oder das Berufungsgericht sie nach Ermessensüberprüfung gemäß R. 220.4 VerfO zulässt (EPG-BerG EOFlow/Insulet).",
                  "Der Hilfsantrag rettet EOFlow: Der Antrag auf Ermessensüberprüfung ist binnen 15 Kalendertagen nach Ablauf der 15-tägigen Zulassungsfrist des Gerichts erster Instanz zu stellen (R. 220.3 VerfO), muss die Angaben nach R. 221.2 enthalten und ist gebührenpflichtig (R. 370.5 lit. d VerfO). Der ständige Richter lässt die Berufung zu, wenn die Anordnung offensichtlich fehlerhaft ist oder eine Frage grundsätzlicher Bedeutung aufwirft; andernfalls kann er den Antrag ohne Begründung abweisen (R. 220.4 VerfO). Die Berufung selbst hat in diesem Fall keine aufschiebende Wirkung (R. 223.5 VerfO)."],
                 merke="Vollstreckung ist nicht Eilverfahren: Gegen die Zwangsgeldfestsetzung hilft nur Zulassung oder Ermessensüberprüfung.",
                 level=3, concepts=["upc_ermessensueberpruefung", "upc_zwangsgeld", "upc_berufung"], norms=["Art. 73 Abs. 2 EPGÜ", "R. 220.3 VerfO", "R. 220.4 VerfO", "R. 354.4 VerfO"],
                 cases=["upc_coa_eoflow_insulet_zwangsgeld_berufung"], step="step:upc_schema_berufung.1.3"),
            fall("u09a-4", "Tenor heute, Gründe später",
                 "Die Lokalkammer verkündet am Ende der mündlichen Verhandlung am 2. Februar den Tenor: Belkin wird zur Unterlassung verurteilt. Die schriftliche Entscheidung mit Gründen wird am 20. März zugestellt. Belkin legt am 15. Mai Berufung ein. Philips hält die Berufung für verspätet: Die Zweimonatsfrist habe mit der Verkündung des Tenors am 2. Februar begonnen und sei am 2. April abgelaufen; Belkin habe von diesem Tag an gewusst, dass sie unterlegen sei.",
                 "Ist die Berufung verspätet?", False,
                 ["**Nein!** Die Berufungsschrift ist binnen zwei Monaten **nach Zustellung** der Entscheidung einzureichen (Art. 73 Abs. 1 EPGÜ, R. 224.1 lit. a VerfO). Das Gericht kann seine Entscheidung zwar unmittelbar nach der mündlichen Verhandlung verkünden und die Begründung nachreichen (R. 118.7 VerfO); die Frist beginnt aber erst zu laufen, wenn das Gericht erster Instanz eine **Entscheidung mit Gründen** erlässt und zustellt (EPG-BerG Belkin/Philips im Anschluss an Ballino/Kinexon). Nur die begründete Entscheidung lässt die Partei erkennen, ob und womit sie die Berufung begründen kann (R. 226 VerfO).",
                  "Die Frist lief also ab dem 20. März und endete am 20. Mai (R. 300 VerfO); die Berufung vom 15. Mai ist rechtzeitig. Die Berufungsbegründung ist binnen vier Monaten ab Zustellung einzureichen (R. 224.2 lit. a VerfO). Eine Verlängerung dieser Frist nach R. 9.3 lit. a VerfO wird angesichts des strengen Fristenregimes nur unter außergewöhnlichen Umständen gewährt; die Angleichung an eine spätere Frist in einem parallelen Verfahren ist kein solcher Umstand, wenn das Berufungsgericht die Verfahren nach R. 220.5 VerfO gemeinsam verhandeln kann (EPG-BerG bioMérieux/Labrador)."],
                 merke="Die Berufungsfrist läuft ab Zustellung der begründeten Entscheidung, nicht ab Verkündung des Tenors.",
                 level=2, concepts=["upc_berufungsfrist", "upc_fristen"], norms=["Art. 73 Abs. 1 EPGÜ", "R. 224.1 VerfO", "R. 118.7 VerfO", "R. 9.3 VerfO"],
                 cases=["upc_coa_belkin_philips_berufungsfrist", "upc_coa_biomerieux_labrador_fristen"], step="step:upc_schema_berufung.2"),
        ]),
        dict(id="u09b", titel="Beschwer, Anschlussberufung, bedingte Berufung, Streithelfer", einheiten=[
            intro("u09b-0", "Wer darf, und wie: Beschwer und Anschluss",
                  "Berufung kann nur einlegen, wer mit seinen Anträgen ganz oder teilweise **unterlegen** ist (Art. 73 Abs. 1 EPGÜ), in der Sprache der VerfO die „beschwerte Partei“ (R. 220.1 VerfO). Wer die Berufungsfrist versäumt hat, kann sich mit der **Anschlussberufung** anschließen, wenn eine andere Partei Berufung eingelegt hat; sie muss in der Berufungserwiderung enthalten sein, den Anforderungen der R. 225, 226 VerfO genügen und ist gebührenpflichtig (R. 237.1 bis 237.4 VerfO). Wird die Berufung zurückgenommen, gilt auch die Anschlussberufung als zurückgenommen (R. 237.5). Auch die Anschlussberufung setzt Beschwer voraus: Wer gewonnen hat und nur die Begründung ändern will, ist nicht beschwert (EPG-BerG Abbott/Sinocare). Eine Besonderheit ist die **bedingte Widerklage**: Der Beklagte darf seine Widerklage auf Nichtigerklärung unter die Bedingung stellen, dass die Verletzung festgestellt wird; weist das Gericht die Verletzungsklage ab und bescheidet die Widerklage deshalb nicht, ist der Widerkläger beschwert, sobald der Kläger Berufung einlegt, und kann seine Berufung unter der Bedingung einlegen, dass der Kläger Berufung einlegt (Emboline/AorticLab). Weil Verletzungsklage und Widerklage getrennte Klagen sind, braucht es dafür eine gesonderte Berufung und keine Anschlussberufung (AorticLab/Emboline). Der **Streithelfer** (R. 313 ff. VerfO) hat keine eigenständige Stellung: Seine Prozesshandlungen sind nur zulässig, soweit sie die Anträge der unterstützten Partei unterstützen (Strabag/Swarco). Die Rüge der internationalen Zuständigkeit ist in der Berufung verloren, wenn sie in erster Instanz unterblieben ist (Art. 26 Abs. 1 Brüssel-Ia-VO, R. 19.7 VerfO; Sinocare/Abbott).",
                  concepts=["upc_beschwer", "upc_streithilfe", "upc_widerklage_nichtigkeit"], norms=["Art. 73 Abs. 1 EPGÜ", "R. 220.1 VerfO", "R. 237 VerfO", "R. 313 VerfO"]),
            fall("u09b-1", "Gewonnen, aber mit der falschen Begründung",
                 "Die Zentralkammer weist die Nichtigkeitsklage von Sinocare gegen das Patent von Abbott ab: Der Anspruch sei neu und erfinderisch. Sinocare legt Berufung ein. Abbott legt in der Berufungserwiderung Anschlussberufung ein mit dem Ziel, dass das Berufungsgericht die erfinderische Tätigkeit auf einen anderen, aus Abbotts Sicht tragfähigeren Grund stützt; am Ergebnis der Klageabweisung will Abbott nichts ändern.",
                 "Ist die Anschlussberufung von Abbott zulässig?", False,
                 ["**Nein!** Berufung und Anschlussberufung setzen voraus, dass die Partei durch die Entscheidung **beschwert** ist (Art. 73 Abs. 1 EPGÜ, R. 220.1, R. 237 VerfO). Beschwert ist, wer mit seinen Anträgen ganz oder teilweise unterlegen ist. Abbott hat vollständig obsiegt: Die Nichtigkeitsklage wurde abgewiesen. Eine Anschlussberufung, die nur die **Begründung** der für sie günstigen Entscheidung ändern will, ist unzulässig (EPG-BerG Abbott/Sinocare).",
                  "Abbott braucht die Anschlussberufung auch nicht: Als Berufungsbeklagte kann sie in der Berufungserwiderung alle Gründe vortragen, die das Ergebnis tragen, auch solche, die das Gericht erster Instanz nicht oder anders gewürdigt hat (R. 235, 236 VerfO). Das Berufungsgericht prüft die angegriffene Entscheidung im Rahmen der Anträge und Gründe der Parteien (R. 222.1 VerfO) und kann die Abweisung mit anderer Begründung bestätigen. Beschwer entsteht erst durch den Tenor, nicht durch die Gründe."],
                 merke="Beschwer liegt im Tenor: Wer gewonnen hat, kann nicht anschließen, nur um die Gründe zu tauschen.",
                 level=2, concepts=["upc_beschwer", "upc_berufung"], norms=["R. 237 VerfO", "R. 220.1 VerfO", "Art. 73 Abs. 1 EPGÜ"],
                 cases=["upc_coa_abbott_sinocare_erfinderisch"], step="step:upc_schema_berufung.3"),
            fall("u09b-2", "Die bedingte Berufung des Widerklägers",
                 "AorticLab wird von Emboline auf Verletzung verklagt und erhebt Widerklage auf Nichtigerklärung unter der Bedingung, dass das Gericht die Verletzung feststellt. Die Lokalkammer weist die Verletzungsklage ab und bescheidet die Widerklage deshalb nicht. Emboline legt Berufung ein. AorticLab legt daraufhin ihrerseits Berufung ein, unter der Bedingung, dass die Berufung von Emboline durchgeführt wird, und will die Berufungsgebühr erst zahlen, wenn die Bedingung eintritt. Emboline hält das für unzulässig: AorticLab habe gewonnen und sei nicht beschwert; eine bedingte Berufung kenne die VerfO nicht, allenfalls sei eine Anschlussberufung möglich.",
                 "Ist die bedingte Berufung von AorticLab zulässig?", True,
                 ["**Ja!** Eine Widerklage auf Nichtigerklärung darf unter die Bedingung einer Verletzungsfeststellung gestellt werden. Weist das Gericht die Verletzungsklage ab und entscheidet es die Widerklage deshalb nicht, ist der Widerkläger **beschwert**, sobald der Kläger Berufung einlegt: Stellt das Berufungsgericht die Verletzung fest, tritt die Bedingung ein, und die unbeschiedene Widerklage muss entschieden werden. AorticLab kann die Berufung deshalb unter der Bedingung einlegen, dass Emboline Berufung einlegt; die Gebühr wird erst mit Bedingungseintritt fällig (EPG-BerG Emboline/AorticLab).",
                  "Der Weg über die Anschlussberufung ist nicht der richtige: Verletzungsklage und Widerklage auf Nichtigerklärung sind nach EPGÜ und VerfO **getrennte Klagen**; die Bedingung ist eine „inter-prozedurale“ Bedingung, die eine gesonderte Berufung erfordert (EPG-BerG AorticLab/Emboline). In der Berufung bleibt die Widerklage bedingt, sofern die Bedingung nicht nach R. 263 analog und R. 222.2 VerfO fallengelassen wird. Stellt das Berufungsgericht die Verletzung fest, entscheidet es die Widerklage in der Regel selbst (Art. 75 Abs. 1 EPGÜ, R. 242.2 lit. b VerfO); dass das Gericht erster Instanz eine Frage nicht entschieden hat („failed to decide“), ist kein Ausnahmefall, der die Zurückverweisung rechtfertigt."],
                 merke="Bedingte Widerklage, bedingte Berufung: Der Widerkläger ist beschwert, sobald der Kläger in die Berufung geht – gesondert, nicht als Anschluss.",
                 level=3, concepts=["upc_beschwer", "upc_widerklage_nichtigkeit", "upc_berufungsfrist"], norms=["R. 220.1 VerfO", "R. 237 VerfO", "Art. 33 Abs. 3 EPGÜ", "R. 242.2 VerfO"],
                 cases=["upc_coa_emboline_aorticlab_bedingte_widerklage", "upc_coa_aorticlab_emboline_getrennte_klagen"], step="step:upc_schema_berufung.3"),
            fall("u09b-3", "Der Streithelfer will weiterkämpfen",
                 "Swarco ist dem Verletzungsverfahren von Strabag gegen eine Zulieferin als Streithelferin auf Seiten der Beklagten beigetreten. Beklagte und Swarco legen gegen das Unterlassungsurteil Berufung ein. Dann schließt die Beklagte mit Strabag einen Vergleich und nimmt ihre Berufung zurück. Swarco widerspricht der Rücknahme und will ihre eigene Berufung fortführen, weil das Urteil auch ihre Produkte betreffe.",
                 "Kann Swarco die Berufung nach der Rücknahme durch die Beklagte fortführen?", False,
                 ["**Nein!** Der Streithelfer unterstützt eine Partei (R. 313 VerfO); seine Prozesshandlungen sind nur zulässig, soweit sie deren Anträge unterstützen, und er darf sich **nicht in Widerspruch** zu Handlungen der unterstützten Partei setzen. Der Widerspruch gegen die Rücknahme der Berufung ist deshalb unzulässig. Haben Partei und Streithelfer Berufung eingelegt, ist das ein **einheitliches Rechtsmittel**, das mit der Rücknahme durch die Partei infolge des Vergleichs gegenstandslos wird und nach R. 360 VerfO erledigt ist (EPG-BerG Strabag/Swarco).",
                  "Scheidet die unterstützte Partei aus dem Verfahren aus, wird die Streithilfe unzulässig; eine eigenständige Fortführung kennt die VerfO nicht, anders als die streitgenössische Nebenintervention des § 69 ZPO. Kostenrechtlich wird der Streithelfer wie die Hauptpartei behandelt, trägt also seine Kosten der erledigten Berufung nach den für die Partei geltenden Regeln. Will Swarco das Patent angreifen, bleibt ihr die eigene Nichtigkeitsklage vor der Zentralkammer (Art. 47 Abs. 6 EPGÜ)."],
                 merke="Der Streithelfer folgt der Partei: Nimmt sie die Berufung zurück, ist auch seine erledigt.",
                 level=2, concepts=["upc_streithilfe", "upc_ruecknahme"], norms=["R. 313 VerfO", "R. 360 VerfO", "R. 265 VerfO"],
                 cases=["upc_coa_strabag_swarco_streithilfe"], step="step:upc_schema_berufung.3"),
        ]),
        dict(id="u09c", titel="Aufschiebende Wirkung, neues Vorbringen, Entscheidung, Wiederaufnahme", einheiten=[
            intro("u09c-0", "Was die Berufung bewirkt und was das Berufungsgericht tut",
                  "Die Berufung hat **keine aufschiebende Wirkung**; erstinstanzliche Entscheidungen sind trotz Berufung vollstreckbar (Art. 74 Abs. 1 EPGÜ, R. 354.1 VerfO). Ausnahmen: Entscheidungen über Nichtigkeitsklagen und Widerklagen auf Nichtigerklärung sowie über Klagen gegen Entscheidungen des EPA haben stets aufschiebende Wirkung (Art. 74 Abs. 2), und das Berufungsgericht kann sie auf begründeten Antrag anordnen (Art. 74 Abs. 1 Satz 2, R. 223 VerfO). Dafür verlangt es außergewöhnliche Umstände, etwa einen offensichtlichen Fehler oder einen unverhältnismäßigen, nicht wiedergutzumachenden Schaden; ein Verstoß gegen das rechtliche Gehör kann ein solcher Umstand sein (Siemens/Hologic). Der Antrag muss vollständig sein (Amycel). Gegenstand des Berufungsverfahrens sind die Anträge, Tatsachen, Beweismittel und Rechtsausführungen der Parteien (R. 222.1); **neues Vorbringen** kann das Berufungsgericht außer Acht lassen, wobei es prüft, ob es in erster Instanz vernünftigerweise nicht möglich war, wie erheblich es ist und wie die Gegenseite dazu steht (R. 222.2 VerfO; Hefei/Grundfos, Onward/Niche). Das Berufungsgericht weist die Berufung zurück oder hebt die Entscheidung ganz oder teilweise auf und **ersetzt sie durch eine eigene**, auch zu den Kosten beider Instanzen (Art. 75 Abs. 1 EPGÜ, R. 242.1 VerfO); es kann alle Befugnisse des Gerichts erster Instanz ausüben und verweist nur in Ausnahmefällen zurück (R. 242.2, R. 243). Die Aufhebung wirkt in der Regel **zurück**: Die erstinstanzliche Anordnung gilt als nie wirksam gewesen, festgesetzte Zwangsgelder verlieren ihre Grundlage (Kodak/Fujifilm 2026). Gegen die rechtskräftige Entscheidung bleibt nur die **Wiederaufnahme** nach Art. 81 EPGÜ, R. 245 ff. VerfO: bei einer entscheidenden neuen Tatsache, die auf einer strafbaren Handlung beruht, oder bei einem grundlegenden Verfahrensfehler, binnen zehn Jahren ab Entscheidung und zwei Monaten ab Entdeckung.",
                  concepts=["upc_aufschiebende_wirkung", "upc_neues_vorbringen_berufung", "upc_wiederaufnahme"], norms=["Art. 74 EPGÜ", "R. 222.2 VerfO", "Art. 75 Abs. 1 EPGÜ", "Art. 81 EPGÜ"],
                  cases=["upc_coa_kodak_fujifilm_aufhebung_zwangsgeld", "upc_coa_siemens_hologic_gehoer"]),
            fall("u09c-1", "Der nachgeschobene Antrag",
                 "Amycel wird erstinstanzlich zur Unterlassung verurteilt und legt Berufung ein. Zugleich beantragt sie die Anordnung der aufschiebenden Wirkung nach R. 223 VerfO und begründet dies knapp mit drohenden Umsatzeinbußen. Der ständige Richter weist den Antrag zurück. Zwei Wochen später stellt Amycel einen zweiten Antrag, jetzt mit einem Gutachten zur Existenzgefährdung und dem Argument, das Urteil beruhe auf einem offensichtlichen Fehler bei der Anspruchsauslegung – Umstände, die ihr schon beim ersten Antrag bekannt waren.",
                 "Ist der zweite Antrag zulässig?", False,
                 ["**Nein!** Der Grundsatz, dass die Parteien ihren Fall so früh wie möglich **vollständig** vortragen (Präambel VerfO Nr. 7, front-loaded procedure), gilt auch für den Antrag auf aufschiebende Wirkung: Er muss nach R. 223.2 VerfO alle Gründe, Tatsachen, Beweismittel und rechtlichen Ausführungen enthalten. Ein späterer weiterer Antrag ist unzulässig, es sei denn, er stützt sich auf Vorbringen, das im ersten Antrag vernünftigerweise nicht möglich war (EPG-BerG Amycel). Gutachten und Auslegungsrüge waren Amycel schon beim ersten Antrag verfügbar.",
                  "In der Sache hätte Amycel von Anfang an darlegen müssen, dass **außergewöhnliche Umstände** vorliegen: Die Berufung hat nach Art. 74 Abs. 1 EPGÜ grundsätzlich keine aufschiebende Wirkung, weil das Übereinkommen die sofortige Vollstreckbarkeit will; nur ein offensichtlicher Fehler der Entscheidung oder ein unverhältnismäßiger, nicht wiedergutzumachender Schaden rechtfertigen die Ausnahme, und eine Verletzung des rechtlichen Gehörs nach Art. 76 Abs. 2 EPGÜ kann ein solcher Umstand sein (EPG-BerG Siemens/Hologic). Bloße Umsatzeinbußen, die der Schadensersatz nach R. 354.2 VerfO ausgleichen kann, genügen nicht. Über den Antrag entscheidet das Berufungsgericht unverzüglich, in Eilfällen der ständige Richter (R. 223.3, 223.4 VerfO)."],
                 merke="Aufschiebende Wirkung nur ausnahmsweise – und der Antrag hat nur einen Schuss: alles beim ersten Mal.",
                 level=2, concepts=["upc_aufschiebende_wirkung", "upc_front_loaded"], norms=["Art. 74 Abs. 1 EPGÜ", "R. 223 VerfO", "Art. 76 Abs. 2 EPGÜ"],
                 cases=["upc_coa_amycel_aufschiebend", "upc_coa_siemens_hologic_gehoer"], step="step:upc_schema_berufung.4"),
            fall("u09c-2", "Alte Druckschrift, neue Lehre",
                 "In der Berufung gegen das Nichtigkeitsurteil stützt Hefei die fehlende erfinderische Tätigkeit auf die Druckschrift D3, die sie schon in erster Instanz vorgelegt hatte, dort aber nur als Beleg für das allgemeine Fachwissen. Nun leitet sie aus einer Zeichnung in D3 erstmals ein konkretes Konstruktionsdetail her, das die Fachperson zur Erfindung geführt haben soll. Zugleich rügt Hefei erstmals die internationale Zuständigkeit des EPG, weil sie ihren Sitz in China habe. Grundfos hält beides für unzulässig.",
                 "Handelt es sich bei der Herleitung aus D3 lediglich um eine zulässige Konkretisierung des erstinstanzlichen Vortrags?", False,
                 ["**Nein!** Ob in zweiter Instanz konkretisiertes Vorbringen **neu** im Sinne der R. 222.2 VerfO ist, hängt davon ab, wie allgemein es in erster Instanz war: Die Konkretisierung eines bereits schlüssigen Vortrags ist nicht neu; die **erstmalige Herleitung konkreter technischer Informationen und Anregungen aus einer bereits vorgelegten Druckschrift** ist dagegen neuer Vortrag (EPG-BerG Hefei/Grundfos). Dass D3 in der Akte war, macht die neue Angriffslinie nicht zum alten Vortrag. Das Berufungsgericht kann sie außer Acht lassen und berücksichtigt dabei, ob Hefei sie mit angemessener Sorgfalt schon erstinstanzlich hätte vorbringen können, wie erheblich sie ist und wie Grundfos dazu steht (R. 222.2 lit. a bis c VerfO). Dasselbe gilt für neue Hilfsanträge des Patentinhabers (Onward/Niche), und die Berufungsbegründung selbst muss vollständig sein (R. 226 VerfO; Knaus Tabbert).",
                  "Die Zuständigkeitsrüge ist erst recht verloren: Wer die Zuständigkeit in erster Instanz nicht mit dem Einspruch nach R. 19 VerfO rügt, hat sich rügelos eingelassen (Art. 26 Abs. 1 Brüssel-Ia-VO, R. 19.7 VerfO) und kann die Rüge in der Berufung grundsätzlich nicht mehr erheben (EPG-BerG Sinocare/Abbott). Berufungskläger müssen zudem darlegen, dass ein gerügter Verfahrensfehler zu einer unrichtigen Entscheidung geführt hat."],
                 merke="R. 222.2: Verdeutlichen ist erlaubt, eine neue technische Lehre aus alter Schrift ist neu – und die Zuständigkeitsrüge gehört in den Einspruch, nicht in die Berufung.",
                 level=3, concepts=["upc_neues_vorbringen_berufung", "upc_front_loaded", "upc_einlassung"], norms=["R. 222.2 VerfO", "R. 226 VerfO", "R. 19.7 VerfO", "Art. 73 Abs. 4 EPGÜ"],
                 cases=["upc_coa_hefei_grundfos_neues_vorbringen", "upc_coa_onward_niche_mittelbar", "upc_coa_sinocare_abbott_zustaendigkeit"], step="step:upc_schema_berufung.5"),
            mc("u09c-3", "Wiederaufnahme nach rechtskräftiger Entscheidung",
                "Welche Aussage zur Wiederaufnahme trifft zu?",
                ["Die Wiederaufnahme ist ein ordentliches Rechtsmittel gegen Entscheidungen des Berufungsgerichts, mit dem jede fehlerhafte Beweiswürdigung gerügt werden kann.",
                 "Ein Antrag wegen eines grundlegenden Verfahrensfehlers ist auf die in Art. 81 Abs. 1 lit. b EPGÜ und R. 247 VerfO genannten Fehler beschränkt; eine unrichtige Würdigung des Standes der Technik gehört nicht dazu.",
                 "Eine neue Tatsache rechtfertigt die Wiederaufnahme, sobald sie dem Antragsteller vor der Entscheidung unbekannt war; auf eine Straftat kommt es nicht an.",
                 "Der Wiederaufnahmeantrag hat stets aufschiebende Wirkung und hemmt die Vollstreckung der Entscheidung."],
                1,
                ["**Richtig ist die zweite Aussage.** Die Wiederaufnahme nach Art. 81 EPGÜ ist ein **außerordentlicher Rechtsbehelf** gegen rechtskräftige Entscheidungen, den das Berufungsgericht nur ausnahmsweise gewährt. Anträge wegen eines grundlegenden Verfahrensfehlers (Art. 81 Abs. 1 lit. b EPGÜ) sind auf die in R. 247 VerfO genannten Fehler beschränkt, etwa die fehlerhafte Besetzung des Spruchkörpers, die Verletzung des rechtlichen Gehörs oder die unterbliebene rechtzeitige Zustellung des verfahrenseinleitenden Schriftstücks an einen nicht erschienenen Beklagten. Eine aus Sicht des Antragstellers falsche Würdigung des Standes der Technik ist kein Verfahrensfehler, sondern ein Angriff auf die Sachentscheidung (EPG-BerG Suinno/Microsoft). Die erste Aussage ist deshalb falsch.",
                 "Die dritte Aussage verkennt Art. 81 Abs. 1 lit. a EPGÜ: Einem Antrag wegen einer neu entdeckten Tatsache von entscheidender Bedeutung darf nur stattgegeben werden, wenn sie auf einer Handlung beruht, die durch eine Endentscheidung eines nationalen Gerichts als **Straftat** qualifiziert wurde; die bloße Unvollständigkeit einer Zeugenaussage genügt nicht. Die vierte Aussage ist falsch: Der Antrag hat **keine** aufschiebende Wirkung, sofern das Berufungsgericht nicht anders entscheidet (Art. 81 Abs. 2 Satz 2 EPGÜ). Fristen: zehn Jahre ab der Entscheidung, spätestens zwei Monate ab Bekanntwerden (Art. 81 Abs. 2 Satz 1); gutgläubige Nutzer des Patents werden geschützt (Abs. 4)."],
                sachverhalt="Das Berufungsgericht hat die Berufung von Suinno gegen Microsoft rechtskräftig zurückgewiesen. Suinno beantragt die Wiederaufnahme nach Art. 81 EPGÜ: Das Berufungsgericht habe den Stand der Technik falsch gewürdigt, und ein Zeuge habe – wie Suinno erst jetzt erkenne – unvollständig ausgesagt.",
                merke="Wiederaufnahme: nur Straftat oder grundlegender Verfahrensfehler nach R. 247 – keine dritte Instanz für die Beweiswürdigung.",
                level=3, concepts=["upc_wiederaufnahme", "upc_rechtliches_gehoer"], norms=["Art. 81 Abs. 1 EPGÜ", "Art. 81 Abs. 2 EPGÜ", "R. 245 VerfO", "R. 247 VerfO"],
                cases=["upc_coa_suinno_microsoft_wiederaufnahme"], step="step:upc_schema_berufung.6"),
        ]),
    ],
)
